pages/sitemap:
{{#partial "page"}}
<h1>{{lang 'sitemap.page_title'}}</h1>

<ul>
{{#each sitemap}}
    <li>
        <h2>{{label}}</h2>
        <ul>
            {{#each body}}
            <li>
                <a href="{{url}}">{{label}}</a>
                {{#if children}}
                    <ul>
                    {{#each children}}
                        {{> components/sitemap/links}}
                    {{/each}}
                    </ul>
                {{/if}}
            </li>
            {{/each}}
            {{#if show_all_link}}
            <li>
                <a href="{{subsection_url}}">{{lang 'sitemap.show_all_link'}}</a>
            </li>
            {{/if}}
        </ul>
    </li>
{{/each}}
</ul>
{{/partial}}
{{> layout/base}}
